<script setup lang="ts">
import {ref,watch,computed} from 'vue';import {request,query as qs} from '../api';import {relationName,type RecordData} from '../model';
const props=defineProps<{show:boolean;title:string;source?:string;items?:{label:string;value:string}[]}>();const emit=defineEmits<{ 'update:show':[boolean];select:[RecordData] }>();const text=ref('');const rows=ref<RecordData[]>([]);const loading=ref(false);const error=ref('');const page=ref(0);const total=ref(0);let turn=0;
const list=computed<RecordData[]>(()=>props.source?rows.value:(props.items||[]).filter(x=>x.label.includes(text.value)||String(x.value).includes(text.value)));
async function load(reset=true){if(!props.source)return;if(loading.value&&!reset)return;const ticket=++turn;loading.value=true;error.value='';try{const p=reset?1:page.value+1;const key=props.source==='project'?'project_name':props.source==='order'?'order_number':'name';const r=await request(`/${props.source}/?`+qs({[key]:text.value,page:p,limit:20}));if(ticket!==turn)return;rows.value=reset?r.data:[...rows.value,...r.data];page.value=p;total.value=r.count||0}catch(e){if(ticket===turn)error.value=(e as Error).message}finally{if(ticket===turn)loading.value=false}}
watch(()=>props.show,(v)=>{if(v){text.value='';rows.value=[];page.value=0;load()}else{turn++;loading.value=false}},{immediate:true});
function choose(row:RecordData){emit('select',row);emit('update:show',false)}
</script><template><van-popup :show="show" @update:show="emit('update:show',$event)" position="bottom" round :style="{height:'82%'}" closeable safe-area-inset-bottom class="picker-popup"><h2>选择{{title}}</h2><van-search v-model="text" :placeholder="`搜索${title}`" @search="load()" @clear="load()" show-action><template #action><button class="search-button" @click="load()">搜索</button></template></van-search><div class="picker-results"><van-cell v-for="row in list" :key="row.id??row.value" :title="source?relationName(source,row):row.label" :label="source==='order'?row.project_name:row.contact_person||''" clickable is-link @click="choose(row)"/><van-loading v-if="loading" class="center-loading"/><p v-if="error" class="form-error" role="alert">{{error}} <button @click="load()">重试</button></p><van-empty v-if="!loading&&!error&&!list.length" description="没有找到匹配项"/><van-button v-if="source&&rows.length<total&&!loading" block plain @click="load(false)">加载更多</van-button></div></van-popup></template>
